put, SUM(u.cache_read) AS cache_read,\n            SUM(u.cache_write_5m) AS cache_write_5m, SUM(u.cache_write_1h) AS cache_write_1h, SUM(u.cache_write_unsplit) AS cache_write_unsplit,\n            COALESCE(SUM(u.est_list_usd_micros), 0) AS est_list_usd_micros,\n            SUM(CASE WHEN u.est_list_usd_micros IS NULL THEN 1 ELSE 0 END) AS unpriced_requests`;\n    function spend(pp, by, from, to) {\n        need(pp, \"spend.read\");\n        if (from && to && from >= to)\n            throw badRequest(\"from must be before to\");\n        const rows = all(`SELECT e.goal_id, u.session_key, s.user_id AS session_owner, u.basis, ${SUM_COLUMNS}\n     FROM v2_usage u\n     JOIN v2_epochs e ON e.ws_id = u.ws_id AND e.session_key = u.session_key AND e.epoch_id = u.epoch_id\n     JOIN v2_sessions s ON s.ws_id = u.ws_id AND s.session_key = u.session_key\n     WHERE u.ws_id = ? AND (? IS NULL OR u.ts >= ?) AND (? IS NULL OR u.ts < ?)\n     GROUP BY e.goal_id, u.session_key, u.basis`, pp.wsId, from, from, to, to);\n        const rolled = all(`SELECT NULLIF(goal_id, '') AS goal_id, '' AS session_key, '' AS session_owner, basis,\n            SUM(requests) AS requests, SUM(input) AS input, SUM(output) AS output, SUM(cache_read) AS cache_read,\n            SUM(cache_write_5m) AS cache_write_5m, SUM(cache_write_1h) AS cache_write_1h, SUM(cache_write_unsplit) AS cache_write_unsplit,\n            SUM(est_list_usd_micros) AS est_list_usd_micros, SUM(unpriced_requests) AS unpriced_requests\n     FROM v2_spend_rollups\n     WHERE ws_id = ? AND (? IS NULL OR day || 'T00:00:00.000Z' >= ?) AND (? IS NULL OR day || 'T00:00:00.000Z' < ?)\n     GROUP BY goal_id, basis`, pp.wsId, from, from, to, to).map((r) => ({ ...r, rolled: true }));\n        const goals = new Map(all(\"SELECT * FROM v2_goals WHERE ws_id = ?\", pp.wsId).map((g) => [g.id, g]));\n        const pods = new Map(all(\"SELECT id, name FROM v2_pods WHERE ws_id = ?\", pp.wsId).map((p) => [p.id, p.name]));\n        const sessions = new Map(all(\"SELECT session_key, title, repo_alias, harness FROM v2_sessions WHERE ws_id = ? AND user_id = ?\", pp.wsId, pp.userId).map((s) => [s.session_key, s]));\n        const total = emptySums();\n        const unallocated = emptySums();\n        const buckets = new Map();\n        const bucket = (key, kind, label, extra = {}) => {\n            let b = buckets.get(key);\n            if (!b)\n                buckets.set(key, (b = { key, kind, label, ...extra, sums: emptySums() }));\n            return b.sums;\n        };\n        for (const r of [...rows, ...rolled]) {\n            add(total, r);\n            if (!r.goal_id) {\n                add(unallocated, r);\n                continue;\n            }\n            const g = goals.get(r.goal_id);\n            const visible = !!g && canReadGoal(pp, goalObj(g));\n            if (by === \"session\") {\n                if (r.rolled) {\n                    add(bucket(\"rolled_up\", \"rolled_up\", \"Older sessions (rolled up)\"), r);\n                    continue;\n                }\n                const mine = r.session_owner === pp.userId ? sessions.get(r.session_key) : undefined;\n                if (mine)\n                    add(bucket(`session:${r.session_key}`, \"session\", mine.title || mine.repo_alias || `${mine.harness} session`, { session_key: r.session_key }), r);\n                else\n                    add(bucket(\"others\", \"others\", \"Other people's sessions\"), r);\n                continue;\n            }\n            if (!visible || !g) {\n                add(bucket(\"private\", \"private\", \"Private goals\"), r);\n                continue;\n            }\n            if (by === \"goal\")\n                add(bucket(`goal:${g.id}`, \"goal\", g.title, { goal: { id: g.id, title: g.title } }), r);\n            else if (g.pod_id)\n                add(bucket(`team:${g.pod_id}`, \"team\", pods.get(g.pod_id) ?? \"Team\", { team: { id: g.pod_id, name: pods.get(g.pod_id) ?? \"\" } }), r);\n            e